using System.Collections.Generic;
using UnityEngine;

namespace FlightSim
{
    /// <summary>
    /// Shader-safe tinted materials for objects created at runtime.
    ///
    /// Never call Shader.Find() at runtime: nothing in the scene references a lit shader,
    /// so the player build strips it and objects render magenta on device. Instead we
    /// clone Resources/FlightSim/DefaultLit.mat (generated by BuildScript.EnsureRuntimeMaterial),
    /// which is always shipped together with its shader.
    /// Materials are cached per colour so identical objects can be batched.
    /// </summary>
    public static class Materials
    {
        public const string BaseMaterialResource = "FlightSim/DefaultLit";

        private static Material _base;
        private static readonly Dictionary<Color, Material> Cache = new Dictionary<Color, Material>();

        public static void Tint(GameObject go, Color color)
        {
            var r = go.GetComponent<Renderer>();
            if (r == null) return;
            r.sharedMaterial = Get(color, r.sharedMaterial);
        }

        private static Material Get(Color color, Material fallback)
        {
            if (Cache.TryGetValue(color, out var cached) && cached != null)
                return cached;

            if (_base == null)
            {
                _base = Resources.Load<Material>(BaseMaterialResource);
                if (_base == null)
                {
                    Debug.LogWarning($"[Materials] Resources/{BaseMaterialResource}.mat not found; " +
                                     "run FlightSim > Create Or Reset Main Scene or the build script.");
                    _base = fallback;
                }
            }

            var mat = new Material(_base) { color = color };
            Cache[color] = mat;
            return mat;
        }
    }
}
